def primes_upto_n(n):
    primes=[]
    cand=2
    while len(primes)<n:
        is_p=True
        for p in primes:
            if p*p>cand: break
            if cand%p==0:
                is_p=False;break
        if is_p: primes.append(cand)
        cand+=1
    return primes

